<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigLoginAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigLoginAccessor trait.
 *
 * Covers null default, string/VO assignment via withLogin,
 * getLogin/login accessors, and isLoginChanged with/without original.
 */
class SmtpOutboundConfigLoginAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withLogin creates a new instance with the Login set
     * from a string value, and getLogin returns the primitive string.
     */
    public function testWithLoginFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigLoginAccessorUnitTest();

        // Act
        $result = $holder->withLogin('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getLogin());
    }
    /**
     * Asserts that withlogin has access to the value object
     * from a string value, and getLogin returns the primitive string.
     */
    public function testWithLoginFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigLoginAccessorUnitTest();

        // Act
        $result = $holder->withLogin('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->login()->value());
    }
    public function testChangedLogin(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigLoginAccessorUnitTest()->withLogin('one');
        $original = $holder->withLogin('one');
        $same = $holder->withLogin('one');
        $modified = $holder->withLogin('other');

        // Act
        $withSame = $original->isLoginChanged($same);
        $withDiferent = $original->isLoginChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigLoginAccessorUnitTest
{
    use SmtpOutboundConfigLoginAccessor;
}
